import java.util.Scanner;

class Employee{
    int employeeId;
    String name;

    Employee(int employeeId, String name){
        this.employeeId = employeeId;
        this.name = name;

    }

}

class PermanentEmployee extends Employee{
    double basicSalary;
    double allowannce;

    PermanentEmployee(int employeeId, String name, double basicSalary, double allowannce){
        super(employeeId, name);
        this.basicSalary = basicSalary;
        this.allowannce = allowannce;

    }
}

class Payroll extends PermanentEmployee{
    int WorkingDays;

    Payroll(int employeeId, String name, double basicSalary, double allowannce,int WorkingDays){
        super(employeeId, name, basicSalary, allowannce);
        this.WorkingDays = WorkingDays;
    }

    void displayDetails(){
        System.out.println("Employee ID: " + employeeId);
        System.out.println("Employee Name: " + name);
        System.out.println("Basic Salary: " + basicSalary);
        System.out.println("Allowance: " + allowannce);
        System.out.println("Working Days: " + WorkingDays);

        double grossSalary = basicSalary+allowannce;
        System.out.println("Gross Salary: " + grossSalary);

        double finalSalary = (grossSalary/30.0)*WorkingDays;

        System.out.printf("Final Salary: %.2f\n", finalSalary);

    }
}

public class Main{
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);

        int id = sc.nextInt();
        String name = sc.next();
        double basic = sc.nextDouble();
        double allowance = sc.nextDouble();
        int days = sc.nextInt();

        Payroll p = new Payroll (id, name, basic, allowance, days);
        p.displayDetails();
        sc.close();
    }
}

